ALTER TABLE "atendeia_aulas" ADD CONSTRAINT "atendeia_aulas_limites" CHECK (("atendeia_aulas"."capacidade" IS NULL OR "atendeia_aulas"."capacidade" BETWEEN 1 AND 100) AND ("atendeia_aulas"."dia_semana" IS NULL OR "atendeia_aulas"."dia_semana" BETWEEN 0 AND 6) AND "atendeia_aulas"."duracao" BETWEEN 15 AND 240 AND "atendeia_aulas"."idade_minima">=0 AND "atendeia_aulas"."idade_maxima">="atendeia_aulas"."idade_minima" AND "atendeia_aulas"."idade_maxima"<=120);
